function dataRows(){return Array.from({length:Math.max(0,meta.end-1)},(_,i)=>i+2).filter(r=>Array.from({length:Math.min(meta.inputCols||6,meta.cols)},(_,c)=>engine.raw(L(c)+r)).some(v=>v!==''));}
function matchRow(r){const fs=meta.filters.filter(f=>f.column&&String(f.value)!=='');const checks=fs.map(f=>T.match(engine.get(f.column+r),f.operator,f.value));if(fs.length&&!(meta.join==='OR'?checks.some(Boolean):checks.every(Boolean)))return false;return !meta.search||Array.from({length:meta.cols},(_,c)=>String(engine.get(L(c)+r))).join(' ').toLowerCase().includes(meta.search.toLowerCase());}
