function visible(){return dataRows().filter(matchRow);}function ordered(){const rows=dataRows();rows.sort((a,b)=>{for(const sort of meta.sort){const x=engine.get(sort.column+a),y=engine.get(sort.column+b),cmp=typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),undefined,{numeric:true});if(cmp)return sort.direction==='desc'?-cmp:cmp;}return a-b;});const set=new Set(rows);return[...rows,...Array.from({length:meta.rows-1},(_,i)=>i+2).filter(r=>!set.has(r))];}
