function insights(){const data=pivotData(),p=meta.pivot;return `<section class="studio-insights"><div class="card"><div class="flex-between"><h2>Live pivot summary</h2><span class="tag">${visible().length} RECORDS</span></div><div class="row slicer-row"><label>Slicer field<select id="slicer-field">${options(meta.slicerField||p.group)}</select></label><div id="slicer-buttons">${slicerButtons()}</div></div><div class="table-scroll"><table class="data"><thead><tr><th>${E(field(p.group))}</th>${(p.column?data.columns:[p.aggregate+' '+field(p.measure)]).map(c=>`<th>${E(c)}</th>`).join('')}${p.column?`<th>Total (${E(p.aggregate)})</th>`:''}</tr></thead><tbody>${data.rows.map(r=>`<tr><td>${E(r.key)}</td>${r.values.map(v=>`<td>${v==null?'—':T.format(v)}</td>`).join('')}${p.column?`<td>${r.total==null?'—':T.format(r.total)}</td>`:''}</tr>`).join('')}<tr class="pivot-grand"><th>Grand total</th>${p.column?data.columns.map(c=>'<td></td>').join(''):''}<th>${data.grand==null?'—':T.format(data.grand)}</th></tr></tbody></table></div><p class="notice">${E(p.aggregate)} uses the chosen values. Count counts records. The grand mean is calculated from individual records, not an unweighted average of group means. All filters and slicers affect this view.</p></div><div class="card"><div class="flex-between"><h2>Your visualisation</h2><button class="btn secondary small" data-do="tool-insights">Chart settings</button></div><div id="studio-chart">${svgChart(data)}</div></div></section>`;}
function slicerButtons(){const col=meta.slicerField||meta.pivot.group,vals=[...new Set(dataRows().map(r=>String(engine.get(col+r))))].filter(Boolean).slice(0,12),active=meta.filters.find(f=>f.slicer)?.value;return `<button class="${active?'':'active'}" data-slicer="">All</button>`+vals.map(v=>`<button class="${v===active?'active':''}" data-slicer="${E(v)}">${E(v)}</button>`).join('');}
function audit(){const invalid=[],errors=[];for(const [ref,rule]of Object.entries(meta.validations))if(engine.raw(ref)!==''&&!T.valid(engine.get(ref),rule))invalid.push(ref);for(const ref of Object.keys(engine.cells))if(/^#/.test(String(engine.get(ref))))errors.push(ref);return{invalid,errors};}
