function choose(ref,focus=true,rangeText){const refs=T.range(rangeText||ref);if(!refs.length){toast('Choose a cell or range between A1 and P120.');return;}meta.selected=refs[0];meta.selection=rangeText||ref;meta.rows=Math.max(meta.rows,...refs.map(r=>P(r).row));meta.cols=Math.max(meta.cols,...refs.map(r=>P(r).col+1));if(!$(`[data-cell="${meta.selected}"]`)){draw();}const selectedSet=new Set(refs);$$('[data-ref]').forEach(td=>{td.classList.toggle('selected',td.dataset.ref===meta.selected);td.classList.toggle('in-range',selectedSet.has(td.dataset.ref));});$('#cell-ref').value=meta.selection;$('#formula-input').value=String(engine.raw(meta.selected));$('#selection-status').textContent=status();renderValidationPicker();if(focus){const input=$(`[data-cell="${meta.selected}"]`);suppressFocus=true;input.focus();input.scrollIntoView({block:'nearest',inline:'nearest'});suppressFocus=false;}persist();}
function commit(ref,value,redraw=true){if(pack.id==='challenge'&&lab.challengeFinished){toast('This attempt is finished. Generate another challenge for fresh practice.');return false;}if(String(engine.raw(ref))===String(value))return true;const rule=meta.validations[ref];if(rule){const map=T.clone(book.sheets),probe=new SheetEngine(map[book.activeSheet],{sheets:map,activeSheet:book.activeSheet});probe.set(ref,value);if(!T.valid(probe.get(ref),rule)){toast(rule.type==='list'?'Choose an allowed value: '+rule.values.join(', '):'Enter '+(rule.type==='whole'?'a whole number':'a number')+' from '+rule.min+' to '+rule.max+'.');if($('#formula-input'))$('#formula-input').value=String(engine.raw(ref));return false;}}
snapshot();feedback='';engine.set(ref,value);editing=false;persist();if(redraw)draw();return true;}
function beginEdit(input,clear=false){if(pack.id==='challenge'&&lab.challengeFinished)return;editing=true;input.readOnly=false;input.value=clear?'':String(engine.raw(input.dataset.cell));if(!clear)input.select();}
function markHelp(key){const l=activeLesson();(lab.help[pack.id+'-'+l.id] ||= {})[key]=true;persist();}
function filtersCorrect(rule){const needed=rule.filters||[];return meta.join!=='OR'&&needed.every(f=>meta.filters.some(a=>a.column===f.column&&a.operator===f.operator&&String(a.value).toLowerCase()===String(f.value).toLowerCase()))&&(rule.count==null||visible().length===rule.count);}
function resultFor(l){const rule=l.rule||{};if(/clear(?: all)?(?: the)? filters/i.test(l.task)&&(meta.filters.some(f=>f.column&&String(f.value)!=='')||meta.search))return{ok:false,reason:'Clear all filters, slicers and record searches as requested before comparing the full dataset.'};const expectedSheet=l.sheet||book.sourceSheet;if(!(l.kind==='clean'&&rule.duplicateKey)&&!(l.kind==='sort'&&meta.sortedBy)&&expectedSheet!==book.activeSheet)return{ok:false,reason:'Switch to the '+expectedSheet+' sheet for this exercise. Each worksheet has its own cell addresses.'};if(l.kind==='formula'||l.kind==='linked'){
 if(rule.filters&&!filtersCorrect(rule))return{ok:false,reason:'Apply the requested filters together before calculating the visible records.'};
 const raw=String(engine.raw(l.cell)).replace(/'/g,'').toUpperCase();if(rule.contains&&!rule.contains.every(s=>raw.includes(s.replace(/'/g,'').toUpperCase())))return{ok:false,reason:'Use the requested fixed, relative or cross-sheet references. Inspect the formula itself, not just its displayed value.'};
 if(rule.fill){const filled=T.checkFill(engine,l);if(!filled.ok)return filled;}
 return T.checkFormula(engine,l);
 }
 if(l.kind==='filter')return{ok:filtersCorrect(rule),reason:'Check both column filters, the comparison operators and AND. Clear extra slicers if they change the requested records.'};
 if(l.kind==='format')return{ok:T.range(rule.range).every(r=>meta.formats[r]?.type===rule.format),reason:'Select the full requested range and apply the requested number format in Home.'};
 if(l.kind==='validation'){const ok=T.range(rule.range).every(ref=>{const v=meta.validations[ref];return v&&v.type===rule.type&&(v.type==='list'?JSON.stringify([...v.values].map(String).sort())===JSON.stringify([...rule.values].map(String).sort()):Number(v.min)===rule.min&&Number(v.max)===rule.max);});return{ok,reason:'Select the complete range, then apply the correct rule under Forms & what-if. Existing data is not automatically corrected.'};}
 if(l.kind==='conditional'){const c=meta.conditional;return{ok:!!c&&c.operator===rule.operator&&Number(c.value)===rule.value&&T.range(rule.range).every(r=>T.range(c.range).includes(r)),reason:'Select the requested range and set its threshold rule in Forms & what-if.'};}
 if(l.kind==='clean'){if(rule.cell)return{ok:T.equal(engine.get(rule.cell),rule.equals),reason:'Verify the source, then correct the specified cell.'};return{ok:meta.cleanedFrom&&meta.cleanKey===rule.duplicateKey&&dataRows().length===rule.expectedRows,reason:'Use Data & cleaning → Create deduplicated copy, with the requested identifier as the duplicate key.'};}
 if(l.kind==='pivot')return{ok:meta.pivot.group===rule.group&&meta.pivot.measure===rule.measure&&meta.pivot.aggregate===rule.aggregate,reason:'Choose the requested category, number field and aggregation in Pivot & charts. Sum, Count and Mean answer different questions.'};
 if(l.kind==='chart')return{ok:meta.pivot.type===rule.type&&(rule.type==='scatter'?meta.pivot.x===rule.x&&meta.pivot.y===rule.y:meta.pivot.group===rule.x&&meta.pivot.measure===rule.y&&(!rule.aggregate||meta.pivot.aggregate===rule.aggregate)),reason:'Check the chart type and the actual fields being plotted. Category charts use pivot rows/values; scatter charts use paired numeric X/Y columns.'};
 if(l.kind==='sort')return{ok:meta.sort[0]?.column===rule.column&&meta.sort[0]?.direction===rule.direction||meta.sortedBy?.column===rule.column&&meta.sortedBy?.direction===rule.direction,reason:'Apply the requested sort column and direction under Data & cleaning.'};
 return{ok:false,reason:'Use the practical guide and verify this skill in Excel Online.'};}
function checkLesson(){const l=activeLesson(),r=resultFor(l),key=pack.id+'-'+l.id;feedbackBad=!r.ok;if(r.ok){lab.completed[key]=lab.help[key]?.hint||lab.help[key]?.solution?'guided':'independent';feedback='<strong>Correct'+(lab.completed[key]==='guided'?' · with support':'')+'.</strong> '+E(l.why);if(l.cell)feedback+=' <span>Current result: '+E(T.format(engine.get(l.cell)))+'.</span>';}else feedback='<strong>Keep going.</strong> '+E(r.reason);persist();draw();}
function nextLesson(delta){lab.cursor[pack.id]=Math.max(0,Math.min(pack.lessons.length-1,(lab.cursor[pack.id]||0)+delta));feedback='';const l=activeLesson();const sheet=l.sheet||book.sourceSheet;if(book.sheets[sheet])book.activeSheet=sheet;bindBook();if(l.cell){meta.selected=l.cell;meta.selection=l.cell;}persist();draw();if(l.cell)choose(l.cell);}
function uniqueName(base){let name=base.slice(0,26),i=2;while(book.sheets[name])name=base.slice(0,23)+' '+i++;return name;}
function addSheet(name,cells={},newMeta={}){const n=uniqueName(name);book.sheets[n]=cells;book.meta[n]={...T.clone(meta),end:1,inputCols:Math.min(8,meta.cols),formats:{},validations:{},filters:[],search:'',sort:[],conditional:null,selected:'A1',selection:'A1',...newMeta};book.activeSheet=n;return n;}
