function exportCSV(){const rows=Array.from({length:meta.end},(_,i)=>Array.from({length:meta.cols},(_,c)=>engine.get(L(c)+(i+1))));download(book.activeSheet.replace(/[^a-z0-9-]/gi,'_')+'.csv',T.csv(rows),'text/csv;charset=utf-8');toast('Exported current values. Export a progress backup to retain formulas and all sheets.');}
